454	    // ---- media -----------------------------------------------------------
455	
456	    /// Adds one probed file to the media list. `descriptor` is the spec
457	    /// §5.2 `media[]` element MINUS `id` — the host probes the file and
458	    /// fills in kind, duration, size, rate and the track flags.
459	    ///
460	    /// **The new media's id is the project's `next_id` BEFORE this call.**
461	    /// There is one JSON op entry point (spec §11), so an op cannot return
462	    /// a value; reading `next_id` first is how the caller learns the id it
463	    /// is about to be able to `add_clip` with.
464	    ///
465	    /// Adding a file whose path is already in the list changes nothing (an
466	    /// identity): two entries for one path would each carry their own
467	    /// bookmark, thumbnails and peaks, and relinking one would leave the
468	    /// other missing. The caller that gets it looks the path up to find the
469	    /// id that is already there.
470	    ///
471	    /// `Err` for a descriptor that is not an object, an unknown or `id`
472	    /// key, a value that does not match the schema, an empty path, a
473	    /// negative duration, a media with pixels whose size or rate is not
474	    /// usable, or an `original` with an empty path. An `original` (spec §11
475	    /// #228-O) is stored with its path trimmed and a blank bookmark dropped.
476	    /// A `color` (spec §11 GR-16) is an `Err` in `set_media_color`'s
477	    /// sentences wherever that op would refuse it, `detected` aside.
478	    pub fn add_media(&self, descriptor: &Value) -> Result<Outcome, String> {
479	        let Value::Object(fields) = descriptor else {
480	            return Err(format!(
481	                "a media descriptor must be a json object, not {}",
482	                describe(descriptor)
483	            ));
484	        };
485	        if fields.contains_key("id") {
486	            return Err(format!(
487	                "a media descriptor must not carry an id: the project assigns it (this one gets {})",
488	                self.next_id
489	            ));
490	        }
491	        for key in fields.keys() {
492	            if !MEDIA_KEYS.contains(&key.as_str()) {
493	                return Err(format!("unknown key \"{key}\" in a media descriptor"));
494	            }
495	        }
496	
497	        // Deserializing through `Media` itself means the descriptor's
498	        // schema is the model's schema — `kind` is checked against the
499	        // three variants, `fps` against `[num, den]` — with no second
500	        // spelling of it here. The id is stamped in first because `Media`
501	        // requires one.
502	        let mut with_id = descriptor.clone();
503	        if let Value::Object(map) = &mut with_id {
504	            map.insert("id".to_string(), Value::from(self.next_id));
505	        }
506	        let mut media: Media = serde_json::from_value(with_id)
507	            .map_err(|e| format!("media descriptor does not match the schema: {e}"))?;
508	
509	        media.original = normalize_original(media.original);
510	        check_media_fields(&media)?;
511	        // A descriptor's `color` is the probe's detected Camera Log (spec §11
512	        // GR-16), held to the rules `set_media_color` holds a setting to.
513	        self.check_media_color(&media)?;
514	        let path = media.path.trim().to_string();
515	        if self.media.iter().any(|m| m.path == path) {
516	            return Ok(Outcome::Identity);
517	        }
518	
519	        let mut next = self.clone();
520	        let mut record = media;
521	        record.id = next.allocate_id();
522	        record.path = path;
523	        // An empty bookmark is not a bookmark; storing one would make
524	        // `relink` think the file had been located once.
525	        record.bookmark = record.bookmark.filter(|b| !b.trim().is_empty());
526	        next.media.push(record);
527	        self.finish(next)
528	    }
529	
530	    /// Removes a media entry. Refuses while clips still show it unless
531	    /// `with_clips`, which removes those clips with it (spec §6) — the
532	    /// model has no "missing on purpose" state, and a clip pointing at an
533	    /// id that is gone is what `validate` rejects. The refusal names the
534	    /// clips ([`clip_list`]) and the argument that would let it through.
535	    pub fn remove_media(&self, media: u32, with_clips: bool) -> Result<Outcome, String> {
536	        // A LUT is no clip's source but some clips' look (spec §11 GR-8).
537	        if self.require_media(media)?.kind == MediaKind::Lut {
538	            return self.remove_lut(media, with_clips);
539	        }
540	        // A nest references the project's `media[]` like everything else
541	        // (spec §5.2, one id space), so a clip INSIDE one counts as usage
542	        // and is removed with `with_clips` — but the nest CLIP is not
543	        // itself a user of the media and stays put. Taking it out would
544	        // throw away everything else in the group over one file.
545	        let used: Vec<u32> = self
546	            .every_clip()
547	            .filter(|c| uses_media(c, media))
548	            .map(|c| c.id)
549	            .collect();
550	        if !used.is_empty() && !with_clips {
551	            return Ok(Outcome::Refused(format!(
552	                "media {media} is still used by {}; pass with_clips: true to remove the \
553	                 media and its clips",
554	                clip_list(&used)
555	            )));
556	        }
557	
558	        let mut next = self.clone();
559	        next.clips.retain(|c| !uses_media(c, media));
560	        for nest in next.nests.iter_mut() {
561	            nest.clips.retain(|c| !uses_media(c, media));
562	        }
563	        next.media.retain(|m| m.id != media);
564	        next.clear_hide_silent(media);
565	        self.finish(next)
566	    }
567	}
