import AppKit

// The agent's five TRACK rows: `add_track`, `remove_track`, `move_track`, `set_track` and
// `remove_empty_tracks`. A pure move out of `AgentCatalog.swift` at its size cap (road map
// audio AP10c), spliced back into `catalogJSON()` at the place they stood, so the
// catalog's order is unchanged; nothing else changed.
extension AgentServer {
    /// The track rows, given the track-id sentence the catalog already hoisted.
    func trackTools(trackDescription: String) -> [[String: Any]] {
        return [
            opTool(
                "add_track",
                "Adds an empty track. INDEX 0 IS THE BACK of the layer stack — the bottom lane "
                    + "of the timeline, drawn first — and tracks.count is the front, which is "
                    + "what ⇧⌘N adds and where an overlay belongs.",
                [
                    "index": "Where in the stack (0 = back). Default: the front.",
                    "name": "Track name, e.g. \"Titles\".",
                ]),
            opTool(
                "remove_track",
                "Removes a track. A track that still holds clips is refused unless with_clips "
                    + "is true, which removes them with it.",
                [
                    "track": trackDescription,
                    "with_clips": "Remove the track's clips too (default false).",
                ]),
            opTool(
                "move_track",
                "Reorders the layer stack: the track moves to `index`, 0 being the back. A "
                    + "higher index draws in FRONT of the tracks below it.",
                ["track": trackDescription, "index": "New position."]),
            opTool(
                "set_track",
                "Renames a track, flips its four switches — the track header's toggles, "
                    + "Track ▸ Hide Video / Mute Audio / Lock Track / Solo — or sets its matte, "
                    + "Track ▸ Matte. hidden drops its "
                    + "picture from the composition, muted its sound; locked keeps every ripple, "
                    + "insert and range edit off it; solo silences every OTHER track in its "
                    + "container (the timeline, or a nest's own tracks) that is not also soloed "
                    + "— mute wins on a track that is both, and pictures are untouched. matte "
                    + "makes the track a matte for the track directly behind it in its "
                    + "container: its clips are not drawn, and what they show cuts that track "
                    + "by alpha, inverted alpha, luma or inverted luma — where the matte track "
                    + "shows nothing, the track behind shows uncut; a back-most matte track, or "
                    + "one in front of another matte track, cuts nothing. Its clips still "
                    + "sound. \"none\" makes it an ordinary track again. volume is the track's "
                    + "fader, linear 0–4 (1 is unity, 4 is +12.04 dB, 0 silent), multiplying every "
                    + "clip's own volume on it; pan is −1 (left) … 1 (right), a constant-power "
                    + "balance after each clip's own pan, and a mono source is not panned. Both "
                    + "are refused outside their ranges and play through nests: a nested clip "
                    + "hears its own track's and every enclosing nest clip's track's. compressor "
                    + "and limiter are the track's dynamics, run post-fader on its sub-mix — "
                    + "after every clip, its volume and its pan, compressor then limiter, the "
                    + "ceiling in dBTP on what the track hands the mix — so the track holding a "
                    + "nest clip is that nest's bus. Each takes the clip's own object "
                    + "(get_project's audio.compressor and audio.limiter keys) and REPLACES the "
                    + "whole value, the keys left out taking their defaults; null clears it. "
                    + "Exact in every export; the preview runs them per composition track, "
                    + "approximately. Timeline tracks only: refused inside a scope. Normalize, "
                    + "Loudness, Enhance Voice and Match Audio do not hear them.",
                [
                    // The four switches name the MENU ITEM each one mirrors
                    // and nothing else: what each DOES is the sentence above,
                    // and a sentence written twice is what this candidate
                    // exists to delete. The description an agent reads comes
                    // with these in one tool object, so nothing is lost.
                    "track": trackDescription,
                    "name": "New track name.",
                    "hidden": "Track ▸ Hide Video.",
                    "muted": "Track ▸ Mute Audio.",
                    "locked": "Track ▸ Lock Track.",
                    "solo": "Track ▸ Solo.",
                    "matte": "Track ▸ Matte; \"none\" is its Off.",
                    "volume": "Track ▸ Mix…'s Volume, as a linear gain 0–4.",
                    "pan": "Track ▸ Mix…'s Pan, −1–1.",
                    "compressor": "Track ▸ Mix…'s Compressor: {threshold_db −60–0, ratio 1–20, "
                        + "attack and release in ticks, makeup_db 0–24}, or null for off.",
                    "limiter": "Track ▸ Mix…'s Limit peaks: {ceiling_db −24–0 dBTP, release "
                        + "600–600000 ticks}, or null for off.",
                ]),
            opTool(
                "remove_empty_tracks",
                "Removes every track that holds no clips — Track ▸ Remove Empty Tracks.",
                [:]),
        ]
    }
}

1	//! Tracks, markers and the media list — spec §6, table
2	//! "Tracks, markers, canvas, media".
3	//!
4	//! One `impl Project` block for everything a clip sits *in* rather than
5	//! everything a clip *is*: the track stack, the marker list, and the media
6	//! the clips point at. The fourth member of that table's row, the canvas,
7	//! is `edit_canvas.rs`, cut out of here under the size rule; `edit_clip.rs`
8	//! owns the clips themselves; the rules both obey are written there and called from
9	//! here — [`Project::snapped`] for every tick argument, [`Project::finish`]
10	//! as the single exit that turns an identity result into
11	//! [`Outcome::Identity`] and a broken invariant into `Err`.
12	//!
13	//! Three invariants this module is responsible for:
14	//!
15	//! 1. **A project always has at least one track.** Removing the last one
16	//!    refuses; `remove_empty_tracks` keeps the back-most.
17	//! 2. **Two markers never share a tick.** A marker is how the user names a
18	//!    moment, and two at one moment is a UI the timeline cannot draw. The
19	//!    op that would create the collision is an `Err` naming the time.
20	//! 3. **One media entry per path.** Re-importing a file already in the
21	//!    project changes nothing; the clips reference the entry that is
22	//!    already there.
23	
24	use serde_json::Value;
25	
26	use crate::export::describe;
27	use crate::model::{
28	    Clip, Marker, Media, MediaKind, MediaOriginal, Project, Track, TrackMatte, DEFAULT_MARKER_COLOR,
29	};
30	use crate::model_track::TRACK_VOLUME_MAX;
31	use crate::outcome::Outcome;
32	use crate::props_check::in_range;
33	use crate::time::Ticks;
34	use crate::track_dynamics::{read_compressor, read_limiter};
35	
36	/// Media dimension ceiling. Nothing decodes at this size — it exists so a
37	/// probe that reports garbage (or a hand-written project) cannot put a
38	/// number in the document that later overflows a texture allocation or
39	/// collapses `fit_scale` to zero.
40	const MEDIA_DIMENSION_MAX: u32 = 65536;
41	
42	/// The keys a media descriptor may carry: the spec §5.2 `media[]` element
43	/// MINUS `id`. Spelled out rather than derived from a serialized [`Media`],
44	/// because the point of the list is to NAME a misspelled key — serde would
45	/// silently drop `"widht"` and leave the user with a zero-width media.
46	/// `edit_relink.rs` reads it too, for a relink's probe (which may not carry
47	/// `color`: a relink keeps the media's Camera Log, spec §11 GR-16).
48	pub(crate) const MEDIA_KEYS: [&str; 13] = [
49	    "path",
50	    "bookmark",
51	    "kind",
52	    "duration",
53	    "width",
54	    "height",
55	    "fps",
56	    "has_video",
57	    "has_audio",
58	    "has_alpha",
59	    "original",
60	    "color",
61	    "cursor",
62	];
63	
64	// ---- helpers -------------------------------------------------------------
65	
66	/// Whether `clip` shows `media`. The three media-bound sources name an id;
67	/// text, shape and nest do not (spec §5.2) — a nest clip shows a GROUP, and
68	/// what that group references is asked of its own clips, which live in the
69	/// same id space and are swept alongside the timeline's.
70	fn uses_media(clip: &Clip, media: u32) -> bool {
71	    clip.source.media() == Some(media)
72	}
73	
74	/// The clips of a `with_clips` refusal, as English (deepening D2·3).
75	///
76	/// Both refusals that `with_clips` is the way past — a track that still
77	/// holds clips and a media a clip still shows — name the clips a caller
78	/// would otherwise have to ask for, so this is written once. At most three
79	/// ids are listed and the rest are a count: a media used by two hundred
80	/// clips would otherwise answer with a sentence nothing could read, and the
81	/// first three plus the total is everything the caller acts on.
82	/// Both callers ask only when they have at least one, and the empty arm is
83	/// here anyway: `split_last` rather than `some[..len - 1]`, because the
84	/// index form underflows on an empty slice and the crate's rule is that no
85	/// input may panic (`core/CLAUDE.md`, Errors). A third caller that forgets
86	/// the guard gets a poor sentence rather than a caught panic.
87	pub(crate) fn clip_list(ids: &[u32]) -> String {
88	    let named: Vec<String> = ids.iter().take(3).map(|id| id.to_string()).collect();
89	    let rest = ids.len().saturating_sub(named.len());
90	    match (named.split_last(), rest) {
91	        (None, _) => "no clips".to_string(),
92	        (Some((last, [])), 0) => format!("clip {last}"),
93	        (Some((last, front)), 0) => format!("clips {} and {last}", front.join(", ")),
94	        (Some(_), more) => format!("clips {} and {more} more", named.join(", ")),
95	    }
96	}
97	
98	/// A media's `original` as it is stored (spec §11 #228-O): the path
99	/// trimmed, and a blank bookmark dropped, for the reason `add_media` drops
100	/// a blank media bookmark. An empty path is left for `check_media_fields`
101	/// to refuse by name. `add_media`, a relink's probe and a media row
102	/// `paste` or `paste_attributes` appends (`edit_paste.rs`) all read it.
103	pub(crate) fn normalize_original(original: Option<MediaOriginal>) -> Option<MediaOriginal> {
104	    original.map(|given| MediaOriginal {
105	        path: given.path.trim().to_string(),
106	        bookmark: given.bookmark.filter(|b| !b.trim().is_empty()),
107	    })
108	}
109	
110	/// The checks a media record's fields must pass once the descriptor has
111	/// matched the schema — `add_media`'s, a relink probe's
112	/// (`edit_relink.rs`) and a pasted media row's that `paste` or
113	/// `paste_attributes` appends (`edit_paste.rs`), in one order and one set
114	/// of sentences: an empty
115	/// path, a `lut` row with a picture, sound or duration (`lut.rs`), a
116	/// negative duration, a media with pixels whose size or rate is not
117	/// usable, an original with an empty path, a `cursor` with an empty path or
118	/// on a media without a picture (`cursor_props.rs`, spec §11 CU-39).
119	pub(crate) fn check_media_fields(media: &Media) -> Result<(), String> {
120	    if media.path.trim().is_empty() {
121	        return Err("media path must not be empty".to_string());
122	    }
123	    crate::lut::check_lut_fields(media)?;
124	    if media.duration < 0 {
125	        return Err(format!(
126	            "media duration must not be negative, not {}",
127	            media.duration
128	        ));
129	    }
130	    // Size and rate are only meaningful for a media with pixels: an
131	    // audio file legitimately reports 0×0. A drawing media with a zero
132	    // dimension would make `fit_scale` and the frame recipe's
133	    // `source_size` meaningless.
134	    let draws = media.has_video || matches!(media.kind, MediaKind::Image);
135	    if draws {
136	        if media.width == 0 || media.height == 0 {
137	            return Err(format!(
138	                "a media with pixels must have a positive width and height, not {}x{}",
139	                media.width, media.height
140	            ));
141	        }
142	        if media.width > MEDIA_DIMENSION_MAX || media.height > MEDIA_DIMENSION_MAX {
143	            return Err(format!(
144	                "media dimensions must be at most {MEDIA_DIMENSION_MAX}, not {}x{}",
145	                media.width, media.height
146	            ));
147	        }
148	    }
149	    if media.has_video && !media.fps.is_valid() {
150	        return Err(format!(
151	            "a media with video must have a frame rate with non-zero terms, not [{}, {}]",
152	            media.fps.num, media.fps.den
153	        ));
154	    }
155	    if media
156	        .original
157	        .as_ref()
158	        .is_some_and(|original| original.path.trim().is_empty())
159	    {
160	        return Err("media original path must not be empty".to_string());
161	    }
162	    crate::cursor_props::check_media_cursor(media)
163	}
