165	// ---- the ops -------------------------------------------------------------
166	
167	impl Project {
168	    fn require_marker(&self, id: u32) -> Result<&Marker, String> {
169	        self.marker(id)
170	            .ok_or_else(|| format!("no marker with id {id}"))
171	    }
172	
173	    // ---- tracks ----------------------------------------------------------
174	
175	    /// Inserts a track at `index`, where 0 is the BACK-most (bottom) layer
176	    /// and `tracks.len()` is the front; `None` means the front, which is
177	    /// where a new layer goes (spec §6).
178	    ///
179	    /// The default name is `Track <count + 1>` — named by the count, not by
180	    /// the index, so inserting in the middle does not renumber the tracks
181	    /// above it under the user. A name of only whitespace is treated as
182	    /// absent. `Err` for an index past the end, or (through `finish`) for
183	    /// exceeding the track cap.
184	    pub fn add_track(&self, index: Option<usize>, name: Option<&str>) -> Result<Outcome, String> {
185	        let at = match index {
186	            None => self.tracks.len(),
187	            Some(given) if given <= self.tracks.len() => given,
188	            Some(given) => {
189	                return Err(format!(
190	                    "track index {given} is out of range (0..={})",
191	                    self.tracks.len()
192	                ))
193	            }
194	        };
195	
196	        let mut next = self.clone();
197	        let id = next.allocate_id();
198	        let name = name
199	            .map(str::trim)
200	            .filter(|given| !given.is_empty())
201	            .map(|given| given.to_string())
202	            .unwrap_or_else(|| next.next_track_name());
203	        next.tracks.insert(at, Track::ordinary(id, name));
204	        self.finish(next)
205	    }
206	
207	    /// Removes a track. Refuses on a track that still holds clips unless
208	    /// `with_clips`, which removes those clips with it, and refuses to
209	    /// remove the LAST track: a project always has somewhere to put a clip,
210	    /// and an empty track stack is a UI with nothing to drop onto.
211	    ///
212	    /// Both refusals carry their own sentence. The last-track one is asked
213	    /// FIRST, because `with_clips: true` is the way past the other and past
214	    /// this one it is not: a caller told about the clips would send it and
215	    /// be refused again.
216	    ///
217	    /// `Err` only for an unknown track.
218	    pub fn remove_track(&self, track: u32, with_clips: bool) -> Result<Outcome, String> {
219	        self.require_track(track)?;
220	        if self.tracks.len() <= 1 {
221	            return Ok(Outcome::Refused(format!(
222	                "track {track} is the only track left, and a project must always have one"
223	            )));
224	        }
225	        let held: Vec<u32> = self
226	            .clips
227	            .iter()
228	            .filter(|c| c.track == track)
229	            .map(|c| c.id)
230	            .collect();
231	        if !held.is_empty() && !with_clips {
232	            return Ok(Outcome::Refused(format!(
233	                "track {track} still holds {}; pass with_clips: true to remove the track \
234	                 and its clips",
235	                clip_list(&held)
236	            )));
237	        }
238	
239	        let mut next = self.clone();
240	        next.tracks.retain(|t| t.id != track);
241	        next.clips.retain(|c| c.track != track);
242	        self.finish(next)
243	    }
244	
245	    /// Moves a track to `index` in the stack (0 = back-most), sliding the
246	    /// tracks it passes over the other way — the layer reorder the timeline
247	    /// drag makes (spec §6).
248	    ///
249	    /// `Err` for an unknown track or an index past the end; an identity
250	    /// when the track is already there.
251	    pub fn move_track(&self, track: u32, index: usize) -> Result<Outcome, String> {
252	        let from = self.require_track_index(track)?;
253	        if index >= self.tracks.len() {
254	            return Err(format!(
255	                "track index {index} is out of range (0..{})",
256	                self.tracks.len()
257	            ));
258	        }
259	        if index == from {
260	            return Ok(Outcome::Identity);
261	        }
262	
263	        let mut next = self.clone();
264	        // `from` came from `track_index`, so it addresses a track that is
265	        // there; `index` was just bounds-checked against the same list.
266	        let moved = next.tracks.remove(from);
267	        next.tracks.insert(index, moved);
268	        self.finish(next)
269	    }
270	
271	    /// Sets any subset of a track's fields; an omitted argument keeps its
272	    /// value (spec §6). The name is stored trimmed, and an empty name is
273	    /// allowed — it means "unnamed", and the timeline draws the track's
274	    /// position instead. `matte` makes the track a matte for the track
275	    /// directly behind it, `none` an ordinary track again (spec §11 MT-1);
276	    /// re-choosing the current mode is an identity through `finish`, like
277	    /// every other unchanged field. `volume` (linear, 0…`TRACK_VOLUME_MAX`)
278	    /// and `pan` (−1…1) are the track's fader and balance (spec §11 AU-102);
279	    /// a value outside its range is an `Err` in `in_range`'s sentence.
280	    /// `compressor` and `limiter` (spec §11 AU-150) are read by
281	    /// `track_dynamics.rs`: `null` clears, an object replaces the whole value.
282	    #[allow(clippy::too_many_arguments)]
283	    pub fn set_track(
284	        &self,
285	        track: u32,
286	        name: Option<&str>,
287	        hidden: Option<bool>,
288	        muted: Option<bool>,
289	        locked: Option<bool>,
290	        solo: Option<bool>,
291	        matte: Option<TrackMatte>,
292	        volume: Option<f64>,
293	        pan: Option<f64>,
294	        compressor: Option<&Value>,
295	        limiter: Option<&Value>,
296	    ) -> Result<Outcome, String> {
297	        self.require_track(track)?;
298	        if let Some(volume) = volume {
299	            in_range("volume", volume, 0.0, TRACK_VOLUME_MAX)?;
300	        }
301	        if let Some(pan) = pan {
302	            in_range("pan", pan, -1.0, 1.0)?;
303	        }
304	        let compressor = compressor.map(read_compressor).transpose()?;
305	        let limiter = limiter.map(read_limiter).transpose()?;
306	        let mut next = self.clone();
307	        if let Some(found) = next.tracks.iter_mut().find(|t| t.id == track) {
308	            if let Some(name) = name {
309	                found.name = name.trim().to_string();
310	            }
311	            if let Some(hidden) = hidden {
312	                found.hidden = hidden;
313	            }
314	            if let Some(muted) = muted {
315	                found.muted = muted;
316	            }
317	            if let Some(locked) = locked {
318	                found.locked = locked;
319	            }
320	            if let Some(solo) = solo {
321	                found.solo = solo;
322	            }
323	            if let Some(matte) = matte {
324	                found.matte = matte;
325	            }
326	            if let Some(volume) = volume {
327	                found.volume = volume;
328	            }
329	            if let Some(pan) = pan {
330	                found.pan = pan;
331	            }
332	            if let Some(compressor) = compressor {
333	                found.compressor = compressor;
334	            }
335	            if let Some(limiter) = limiter {
336	                found.limiter = limiter;
337	            }
338	        }
339	        self.finish(next)
340	    }
341	
342	    /// Removes every track that holds no clips — the tidy-up after a big
343	    /// delete (spec §6).
344	    ///
345	    /// If that would empty the stack, the back-most track survives: it is
346	    /// the one a fresh project starts with, and keeping the bottom of the
347	    /// stack means the surviving track is where a drop lands.
348	    pub fn remove_empty_tracks(&self) -> Result<Outcome, String> {
349	        let mut next = self.clone();
350	        next.tracks
351	            .retain(|t| self.clips.iter().any(|c| c.track == t.id));
352	        if next.tracks.is_empty() {
353	            next.tracks = self.tracks.iter().take(1).cloned().collect();
354	        }
355	        self.finish(next)
356	    }
357	
358	    // ---- markers ---------------------------------------------------------
359	
360	    /// Adds a marker at `at`, snapped to the frame grid and clamped to 0 —
361	    /// a drag can start left of the timeline, and there is no negative time
362	    /// (spec §6).
363	    ///
364	    /// The default name is `Marker <count + 1>` and the default colour is
365	    /// `"red"`. `Err` when another marker already holds the tick: two
366	    /// markers may not share a time, and moving the existing one is the
367	    /// caller's decision, not this op's.
368	    pub fn add_marker(
369	        &self,
370	        at: Ticks,
371	        name: Option<&str>,
372	        chapter: Option<bool>,
373	        color: Option<&str>,
374	    ) -> Result<Outcome, String> {
375	        let at = self.snapped(at).max(0);
376	        if let Some(existing) = self.markers.iter().find(|m| m.time == at) {
377	            return Err(format!("marker {} is already at {at} ticks", existing.id));
378	        }
379	
380	        let mut next = self.clone();
381	        let id = next.allocate_id();
382	        let name = name
383	            .map(|given| given.trim().to_string())
384	            .unwrap_or_else(|| format!("Marker {}", next.markers.len().saturating_add(1)));
385	        let color = color
386	            .map(str::trim)
387	            .filter(|given| !given.is_empty())
388	            .unwrap_or(DEFAULT_MARKER_COLOR)
389	            .to_string();
390	        next.markers.push(Marker {
391	            id,
392	            time: at,
393	            name,
394	            color,
395	            chapter: chapter.unwrap_or(false),
396	        });
397	        self.finish(next)
398	    }
399	
400	    /// Sets any subset of a marker's fields; an omitted argument keeps its
401	    /// value. A new time is snapped and clamped to 0 like `add_marker`'s,
402	    /// and collides with another marker the same way (`Err`).
403	    ///
404	    /// An empty `name` is allowed: it clears the label, which is how a
405	    /// marker becomes a plain mark.
406	    pub fn set_marker(
407	        &self,
408	        marker: u32,
409	        time: Option<Ticks>,
410	        name: Option<&str>,
411	        chapter: Option<bool>,
412	        color: Option<&str>,
413	    ) -> Result<Outcome, String> {
414	        self.require_marker(marker)?;
415	        let time = match time {
416	            None => None,
417	            Some(given) => {
418	                let at = self.snapped(given).max(0);
419	                if let Some(other) = self.markers.iter().find(|m| m.id != marker && m.time == at) {
420	                    return Err(format!("marker {} is already at {at} ticks", other.id));
421	                }
422	                Some(at)
423	            }
424	        };
425	
426	        let mut next = self.clone();
427	        if let Some(found) = next.markers.iter_mut().find(|m| m.id == marker) {
428	            if let Some(time) = time {
429	                found.time = time;
430	            }
431	            if let Some(name) = name {
432	                found.name = name.trim().to_string();
433	            }
434	            if let Some(chapter) = chapter {
435	                found.chapter = chapter;
436	            }
437	            // An empty colour falls back to the default rather than being
438	            // stored: the UI has to draw the mark as something.
439	            if let Some(color) = color.map(str::trim).filter(|given| !given.is_empty()) {
440	                found.color = color.to_string();
441	            }
442	        }
443	        self.finish(next)
444	    }
445	
446	    /// Removes a marker. `Err` only for an unknown id.
447	    pub fn remove_marker(&self, marker: u32) -> Result<Outcome, String> {
448	        self.require_marker(marker)?;
449	        let mut next = self.clone();
450	        next.markers.retain(|m| m.id != marker);
451	        self.finish(next)
452	    }
453	
454	    // ---- media -----------------------------------------------------------
455	
456	    /// Adds one probed file to the media list. `descriptor` is the spec
457	    /// §5.2 `media[]` element MINUS `id` — the host probes the file and
458	    /// fills in kind, duration, size, rate and the track flags.
459	    ///
460	    /// **The new media's id is the project's `next_id` BEFORE this call.**
461	    /// There is one JSON op entry point (spec §11), so an op cannot return
462	    /// a value; reading `next_id` first is how the caller learns the id it
463	    /// is about to be able to `add_clip` with.
464	    ///
465	    /// Adding a file whose path is already in the list changes nothing (an
466	    /// identity): two entries for one path would each carry their own
467	    /// bookmark, thumbnails and peaks, and relinking one would leave the
468	    /// other missing. The caller that gets it looks the path up to find the
469	    /// id that is already there.
470	    ///
471	    /// `Err` for a descriptor that is not an object, an unknown or `id`
472	    /// key, a value that does not match the schema, an empty path, a
473	    /// negative duration, a media with pixels whose size or rate is not
474	    /// usable, or an `original` with an empty path. An `original` (spec §11
475	    /// #228-O) is stored with its path trimmed and a blank bookmark dropped.
476	    /// A `color` (spec §11 GR-16) is an `Err` in `set_media_color`'s
477	    /// sentences wherever that op would refuse it, `detected` aside.
478	    pub fn add_media(&self, descriptor: &Value) -> Result<Outcome, String> {
479	        let Value::Object(fields) = descriptor else {
480	            return Err(format!(
481	                "a media descriptor must be a json object, not {}",
482	                describe(descriptor)
483	            ));
484	        };
485	        if fields.contains_key("id") {
486	            return Err(format!(
487	                "a media descriptor must not carry an id: the project assigns it (this one gets {})",
488	                self.next_id
489	            ));
490	        }
491	        for key in fields.keys() {
492	            if !MEDIA_KEYS.contains(&key.as_str()) {
493	                return Err(format!("unknown key \"{key}\" in a media descriptor"));
494	            }
495	        }
496	
497	        // Deserializing through `Media` itself means the descriptor's
498	        // schema is the model's schema — `kind` is checked against the
499	        // three variants, `fps` against `[num, den]` — with no second
500	        // spelling of it here. The id is stamped in first because `Media`
501	        // requires one.
502	        let mut with_id = descriptor.clone();
503	        if let Value::Object(map) = &mut with_id {
504	            map.insert("id".to_string(), Value::from(self.next_id));
505	        }
506	        let mut media: Media = serde_json::from_value(with_id)
507	            .map_err(|e| format!("media descriptor does not match the schema: {e}"))?;
508	
509	        media.original = normalize_original(media.original);
510	        check_media_fields(&media)?;
511	        // A descriptor's `color` is the probe's detected Camera Log (spec §11
512	        // GR-16), held to the rules `set_media_color` holds a setting to.
513	        self.check_media_color(&media)?;
514	        let path = media.path.trim().to_string();
515	        if self.media.iter().any(|m| m.path == path) {
516	            return Ok(Outcome::Identity);
517	        }
518	
519	        let mut next = self.clone();
520	        let mut record = media;
521	        record.id = next.allocate_id();
522	        record.path = path;
523	        // An empty bookmark is not a bookmark; storing one would make
524	        // `relink` think the file had been located once.
525	        record.bookmark = record.bookmark.filter(|b| !b.trim().is_empty());
526	        next.media.push(record);
527	        self.finish(next)
528	    }
529	
530	    /// Removes a media entry. Refuses while clips still show it unless
531	    /// `with_clips`, which removes those clips with it (spec §6) — the
532	    /// model has no "missing on purpose" state, and a clip pointing at an
533	    /// id that is gone is what `validate` rejects. The refusal names the
534	    /// clips ([`clip_list`]) and the argument that would let it through.
535	    pub fn remove_media(&self, media: u32, with_clips: bool) -> Result<Outcome, String> {
536	        // A LUT is no clip's source but some clips' look (spec §11 GR-8).
537	        if self.require_media(media)?.kind == MediaKind::Lut {
538	            return self.remove_lut(media, with_clips);
539	        }
540	        // A nest references the project's `media[]` like everything else
541	        // (spec §5.2, one id space), so a clip INSIDE one counts as usage
542	        // and is removed with `with_clips` — but the nest CLIP is not
543	        // itself a user of the media and stays put. Taking it out would
544	        // throw away everything else in the group over one file.
545	        let used: Vec<u32> = self
546	            .every_clip()
547	            .filter(|c| uses_media(c, media))
548	            .map(|c| c.id)
549	            .collect();
550	        if !used.is_empty() && !with_clips {
551	            return Ok(Outcome::Refused(format!(
552	                "media {media} is still used by {}; pass with_clips: true to remove the \
553	                 media and its clips",
554	                clip_list(&used)
555	            )));
556	        }
557	
558	        let mut next = self.clone();
559	        next.clips.retain(|c| !uses_media(c, media));
560	        for nest in next.nests.iter_mut() {
561	            nest.clips.retain(|c| !uses_media(c, media));
562	        }
563	        next.media.retain(|m| m.id != media);
564	        next.clear_hide_silent(media);
565	        self.finish(next)
566	    }
567	}
