1	//! The document's canvas — spec §6, the `set_canvas` row.
2	//!
3	//! One op and the three things it has to do to the rest of the document
4	//! when it lands: check a dimension, rescale every clip's placement when
5	//! the size changes, and re-snap every stored time when the rate does.
6	//! `edit_track.rs` owns the track stack, the markers and the media list;
7	//! this file was cut out of it under the size rule and is the canvas half
8	//! of the same concern — the document's own shape rather than what sits
9	//! on it.
10	//!
11	//! The two rules worth knowing before reading:
12	//!
13	//! 1. **A canvas dimension is even**, because H.264 and HEVC encode in
14	//!    macroblocks over a chroma-subsampled plane. Catching it here makes
15	//!    it a message about the field the user just typed.
16	//! 2. **A rate change normalizes stored picture times**, so it re-snaps
17	//!    top-level and nested clips and top-level markers to the new grid — and a
18	//!    coarser grid can land two markers on one tick, which markers may
19	//!    never share.
20	
21	use crate::model::{CanvasBlending, CanvasOutput, Color, Project, VideoProps};
22	use crate::outcome::Outcome;
23	use crate::props_check::{color_ok, SCALE_MAX, SCALE_MIN};
24	use crate::time::{self, Fps, Ticks};
25	
26	/// Canvas dimension bounds. The floor is small enough for a thumbnail-sized
27	/// document and large enough that the compositor has pixels to work with;
28	/// the ceiling is past 8K, where a single frame is already 130 MB.
29	///
30	/// `pub(crate)` because `op_rows.rs`'s table publishes this range as `width`'s and
31	/// `height`'s bound: the published bound is SOURCED from the constant the
32	/// refusal below is written against, never retyped beside it.
33	pub(crate) const CANVAS_MIN: u32 = 16;
34	pub(crate) const CANVAS_MAX: u32 = 16384;
35	
36	// ---- helpers -------------------------------------------------------------
37	
38	/// A canvas dimension: inside the bounds AND even.
39	///
40	/// Even is not fussiness: H.264 and HEVC encode in macroblocks over a
41	/// chroma-subsampled plane, so an odd width or height is either refused by
42	/// the encoder or silently padded. Catching it here makes it a message
43	/// about the canvas field the user just typed instead of an export that
44	/// fails an hour later.
45	fn check_dimension(key: &str, value: u32) -> Result<(), String> {
46	    if !(CANVAS_MIN..=CANVAS_MAX).contains(&value) {
47	        return Err(format!(
48	            "{key} must be between {CANVAS_MIN} and {CANVAS_MAX}, not {value}"
49	        ));
50	    }
51	    if !value.is_multiple_of(2) {
52	        return Err(format!(
53	            "{key} must be even (h.264 encodes in macroblocks), not {value}"
54	        ));
55	    }
56	    Ok(())
57	}
58	
59	/// Multiplies every clip's placement by the canvas size ratio, so a layout
60	/// built for one canvas lands in the same relative place on the next (spec
61	/// §6, `rescale_clips`).
62	///
63	/// `x` and `y` are per-axis offsets in canvas pixels, so each follows its
64	/// OWN axis ratio — that is what keeps a layer's distance from an edge
65	/// proportional when the aspect ratio changes too. `scale` is one uniform
66	/// factor and cannot follow two ratios, so it follows the SMALLER of them:
67	/// the same `min` Fit uses, which means a layer that fitted the old canvas
68	/// still fits the new one, where the larger ratio could push it off an
69	/// edge.
70	///
71	/// Action `end` patches are deliberately NOT rescaled: a patch is opaque
72	/// JSON (`actions.rs` interprets it), and the op is defined on the clip's
73	/// props. An animated move on a resized canvas therefore keeps its old
74	/// target, which is visible and fixable, unlike a patch this function
75	/// half-understood and rewrote.
76	fn rescale(project: &mut Project, old_width: u32, old_height: u32) {
77	    if old_width == 0 || old_height == 0 {
78	        return;
79	    }
80	    let width_ratio = f64::from(project.canvas.width) / f64::from(old_width);
81	    let height_ratio = f64::from(project.canvas.height) / f64::from(old_height);
82	    if !(width_ratio.is_finite() && height_ratio.is_finite()) {
83	        return;
84	    }
85	    for clip in project.clips.iter_mut() {
86	        if let Some(video) = clip.video.as_mut() {
87	            rescale_video(video, width_ratio, height_ratio);
88	        }
89	    }
90	}
91	
92	/// One clip's placement under [`rescale`]'s rule: `x` and `y` by their own
93	/// axis's ratio, `scale` by the smaller. `reframe_clip`'s `keep` applies it
94	/// to one clip's base (spec §11 VR-26).
95	pub(crate) fn rescale_video(video: &mut VideoProps, width_ratio: f64, height_ratio: f64) {
96	    let scale_ratio = width_ratio.min(height_ratio);
97	    video.x *= width_ratio;
98	    video.y *= height_ratio;
99	    // Clamped to the same range `set_video` accepts, so a chain of
100	    // shrinks cannot leave a scale the inspector refuses to show.
101	    video.scale = (video.scale * scale_ratio).clamp(SCALE_MIN, SCALE_MAX);
102	}
103	
104	/// Re-snaps stored picture times to the canvas's CURRENT frame grid, after
105	/// that grid has changed.
106	///
107	/// Yesterday's grid is not today's: a 24 fps boundary is not a 30 fps
108	/// boundary, so top-level and stored-nest clips, their action and present
109	/// base motion/text times, and top-level markers move to the new grid.
110	///
111	/// Three clamps keep the result valid: a media clip's duration is held to
112	/// the source it still has, snapped DOWN to the new grid, so a coarser rate
113	/// cannot round a whole-file clip past the end of its file (spec §11); a
114	/// duration that would round to zero becomes one frame (a zero-length clip
115	/// is what `validate` rejects), which is the ONE case the source bound
116	/// cannot hold and `evaluate.rs`'s clamp covers; and an action is kept
117	/// inside its clip — but a ramped clip's speed action, which is snapped and
118	/// left running past the end, the duration held again (spec §11 SR-19 (g)).
119	fn resnap(project: &mut Project) {
120	    let fps = project.canvas.fps;
121	    // Temporarily own each list so source/media lookup can borrow the whole
122	    // project while a clip is normalized. Visit each stored nest exactly
123	    // once, including orphans and nests shown by more than one clip.
124	    let mut clips = std::mem::take(&mut project.clips);
125	    for clip in &mut clips {
126	        project.resnap_clip_times(clip);
127	    }
128	    project.clips = clips;
129	    for index in 0..project.nests.len() {
130	        let mut clips = std::mem::take(&mut project.nests[index].clips);
131	        for clip in &mut clips {
132	            project.resnap_clip_times(clip);
133	        }
134	        project.nests[index].clips = clips;
135	    }
136	    for marker in project.markers.iter_mut() {
137	        marker.time = time::snap_to_frame(marker.time, fps).max(0);
138	    }
139	    // A coarser grid can land two markers on one tick, which markers may
140	    // never share. The alternative — refusing a document-wide rate change
141	    // because two marks are 3 ms apart — is far worse than dropping the
142	    // second of them, so the first in the list keeps the tick.
143	    //
144	    // A linear scan over a `Vec` rather than a set: markers are capped at
145	    // 1024 and this runs only on a rate change.
146	    let mut taken: Vec<Ticks> = Vec::with_capacity(project.markers.len());
147	    project.markers.retain(|marker| {
148	        if taken.contains(&marker.time) {
149	            false
150	        } else {
151	            taken.push(marker.time);
152	            true
153	        }
154	    });
155	}
156	
157	// ---- the op --------------------------------------------------------------
158	
159	impl Project {
160	    /// Sets any subset of the document's canvas fields (spec §6). An
161	    /// omitted argument keeps its value.
162	    ///
163	    /// `rescale_clips` multiplies every clip's `x`, `y` and `scale` by the
164	    /// size ratio (see [`rescale`]) so a finished layout survives a resize.
165	    /// Changing `fps` re-snaps top-level and stored-nest clip times, present
166	    /// base motion/text timing, action spans and top-level markers.
167	    ///
168	    /// `Err` for a dimension outside 16..16384 or odd (H.264 needs even
169	    /// dimensions), a frame rate with a zero term, or a background channel
170	    /// outside 0..1.
171	    ///
172	    /// `output` sets the project's dynamic range (spec §11 HD-2, HD-13):
173	    /// `sdr` or `hlg`. It changes no clip and no grade — a grade's numbers
174	    /// keep their 0…1 meaning — and setting the output the canvas already
175	    /// has is an identity, like every other unchanged field, through
176	    /// `finish`.
177	    ///
178	    /// `blending` sets how layers blend (spec §11 GR-18, HD-16): `encoded`
179	    /// or `linear` light. It changes no clip and no grade, and the blending
180	    /// the canvas already has is an identity through `finish`, as `output`.
181	    ///
182	    /// The rate change is deliberately NOT re-checked against the overlap
183	    /// rule: re-snapping moves each edge by less than one frame, so an
184	    /// overlap can grow by at most a frame, and refusing a document-wide
185	    /// rate change over a one-frame drift would be worse than the drift.
186	    #[allow(clippy::too_many_arguments)]
187	    // The argument list IS the op's argument list (spec §6); a struct would
188	    // hold exactly the same nine optional fields and one more name.
189	    pub fn set_canvas(
190	        &self,
191	        width: Option<u32>,
192	        height: Option<u32>,
193	        fps: Option<Fps>,
194	        background: Option<Color>,
195	        rescale_clips: bool,
196	        fit_new_clips: Option<bool>,
197	        timecode_frames: Option<bool>,
198	        output: Option<CanvasOutput>,
199	        blending: Option<CanvasBlending>,
200	    ) -> Result<Outcome, String> {
201	        let width = match width {
202	            None => self.canvas.width,
203	            Some(given) => {
204	                check_dimension("canvas width", given)?;
205	                given
206	            }
207	        };
208	        let height = match height {
209	            None => self.canvas.height,
210	            Some(given) => {
211	                check_dimension("canvas height", given)?;
212	                given
213	            }
214	        };
215	        let fps = match fps {
216	            None => self.canvas.fps,
217	            Some(given) if given.is_valid() => given,
218	            Some(given) => {
219	                return Err(format!(
220	                    "canvas fps must be [num, den] with non-zero terms, not [{}, {}]",
221	                    given.num, given.den
222	                ))
223	            }
224	        };
225	        if let Some(background) = background.as_ref() {
226	            color_ok("canvas background", background)?;
227	        }
228	
229	        let mut next = self.clone();
230	        next.canvas.width = width;
231	        next.canvas.height = height;
232	        next.canvas.fps = fps;
233	        if let Some(background) = background {
234	            next.canvas.background = background;
235	        }
236	        if let Some(fit_new_clips) = fit_new_clips {
237	            next.canvas.fit_new_clips = fit_new_clips;
238	        }
239	        if let Some(timecode_frames) = timecode_frames {
240	            next.canvas.timecode_frames = timecode_frames;
241	        }
242	        if let Some(output) = output {
243	            next.canvas.output = output;
244	        }
245	        if let Some(blending) = blending {
246	            next.canvas.blending = blending;
247	        }
248	
249	        let resized = width != self.canvas.width || height != self.canvas.height;
250	        if rescale_clips && resized {
251	            rescale(&mut next, self.canvas.width, self.canvas.height);
252	        }
253	        if fps != self.canvas.fps {
254	            resnap(&mut next);
255	        }
256	        self.finish(next)
257	    }
258	}
