//! Reading and checking `set_track`'s `compressor` and `limiter` (format 36,
//! spec §11 AU-150): a track's dynamics, run post-fader on its sub-mix
//! (AU-151). The DSP is the Swift side's (`AudioTrackDynamics.swift`, the
//! export's `ExportMixRead.swift`); nothing here touches a sample.
//!
//! Each argument is three-valued, which a plain `Option<Value>` field cannot
//! tell apart: ABSENT keeps the track's value, `null` clears it, and an
//! object REPLACES it whole — the keys it leaves out take the clip type's
//! defaults, never the stored value's, so what a caller sends is what the
//! track holds. [`present`] is the field's `deserialize_with`, which makes
//! `null` arrive as `Some(Value::Null)` rather than `None`.
//!
//! The refusals are the vocabulary's own rule — a key or a value the type
//! does not have is refused, never dropped (`patch.rs`): `compressor must be
//! a json object or null, not 5`, `unknown key "compressor.knee" in
//! set_track`, `bad value at "limiter.release" in set_track: <serde's
//! reason>`, then the range in `in_range`'s sentence under the track's key
//! (`compressor.ratio must be between 1 and 20, not 30`).

use serde::de::DeserializeOwned;
use serde::{Deserialize, Deserializer, Serialize};
use serde_json::Value;

use crate::audio_dynamics::{check_compressor, check_limiter};
use crate::export::describe;
use crate::model::{Compressor, Limiter};
use crate::patch::path_under;

/// What the refusals call the op.
const SUBJECT: &str = "set_track";

/// `deserialize_with` for an argument whose `null` means something: a
/// present key is `Some` of its value, `null` included; an absent one is the
/// field's `default`, `None`.
pub(crate) fn present<'de, D: Deserializer<'de>>(d: D) -> Result<Option<Value>, D::Error> {
    Value::deserialize(d).map(Some)
}

/// `set_track`'s `compressor`: `null` → `Ok(None)` (clear), an object → the
/// whole compressor, range-checked.
pub(crate) fn read_compressor(v: &Value) -> Result<Option<Compressor>, String> {
    let Some(compressor) = read::<Compressor>("compressor", v)? else {
        return Ok(None);
    };
    check_compressor("compressor", &compressor)?;
    Ok(Some(compressor))
}

/// `set_track`'s `limiter`: `null` → `Ok(None)`, an object → the whole
/// limiter, range-checked.
pub(crate) fn read_limiter(v: &Value) -> Result<Option<Limiter>, String> {
    let Some(limiter) = read::<Limiter>("limiter", v)? else {
        return Ok(None);
    };
    check_limiter("limiter", &limiter)?;
    Ok(Some(limiter))
}

/// The kind, the keys against the type's own default's, then the typed read
/// with the path of whatever only the type can refuse.
fn read<T: DeserializeOwned + Serialize + Default>(
    key: &str,
    v: &Value,
) -> Result<Option<T>, String> {
    let given = match v {
        Value::Null => return Ok(None),
        Value::Object(given) => given,
        other => {
            return Err(format!(
                "{key} must be a json object or null, not {}",
                describe(other)
            ))
        }
    };
    let template = serde_json::to_value(T::default()).unwrap_or(Value::Null);
    for name in given.keys() {
        if template.get(name).is_none() {
            return Err(format!("unknown key \"{key}.{name}\" in {SUBJECT}"));
        }
    }
    serde_path_to_error::deserialize(v.clone())
        .map(Some)
        .map_err(|e| {
            let path = path_under(key, &e.path().to_string());
            format!("bad value at \"{path}\" in {SUBJECT}: {}", e.inner())
        })
}
/// not on taste: every evaluation of a nested layer recurses once per
/// level, and eight levels is already past anything an editor does on
/// purpose. `Project::validate` refuses a deeper file, and it refuses a
/// nest that reaches itself at any depth, so no walk downstream needs a
/// visited set of its own.
pub const MAX_NEST_DEPTH: u32 = 8;

/// The caps check both sides share: [`Project::validate`] runs it on read,
/// [`write`] runs it before serializing. One implementation, so the writer
/// can never produce a file the reader rejects.
///
/// Nested tracks and clips count toward the same two caps as the
/// timeline's. They are the same tracks and clips — a nest is a group held
/// in the parent's one id space, and flattening one at evaluation time
/// gives its clips real composition tracks — so counting them separately
/// would let a project with 64 nests of 64 tracks past a cap that exists to
/// bound exactly that.
pub fn check_caps(p: &Project) -> Result<(), String> {
    let nested_clips: usize = p.nests.iter().map(|n| n.clips.len()).sum();
    let nested_tracks: usize = p.nests.iter().map(|n| n.tracks.len()).sum();
    let clips = p.clips.len().saturating_add(nested_clips);
    let tracks = p.tracks.len().saturating_add(nested_tracks);
    if clips > MAX_CLIPS {
        return Err(format!("too many clips: {clips} (max {MAX_CLIPS})"));
    }
    if tracks > MAX_TRACKS {
        return Err(format!("too many tracks: {tracks} (max {MAX_TRACKS})"));
    }
    if p.markers.len() > MAX_MARKERS {
        return Err(format!(
            "too many markers: {} (max {})",
            p.markers.len(),
            MAX_MARKERS
        ));
    }
    if p.media.len() > MAX_MEDIA {
        return Err(format!(
            "too many media: {} (max {})",
            p.media.len(),
            MAX_MEDIA
        ));
    }
    Ok(())
}

/// Version 1 → 2. One key needs rewriting: a nest clip's `project`.
///
/// In version 1 it was a PATH — a reference the core, which has no
/// filesystem, could never resolve, so `evaluate.rs` could only drop the
/// clip — and in version 2 it is the id of a `Nest` in `nests[]`. No build
/// ever created one (no op makes a nest yet; the reader round-tripped the
/// key and nothing else), so nothing real is being reinterpreted here. The
/// step exists because "the reader accepts every prior version" is a
/// promise about hand-written and third-party files too, and a `String`
/// where a `u32` now belongs is the one version-1 shape serde cannot take
/// with a default.
///
/// The path becomes an EMPTY nest carrying it as a name. That keeps the
/// clip — its track, its times, its transform, its actions — and loses only
/// a reference that never resolved to anything; deleting the clip instead
/// would silently throw away something a person placed on a timeline.
///
/// Anything else is left exactly as it is. A shape this cannot make sense
/// of gets serde's schema error, naming the key, rather than a guess made
/// here.
fn migrate_1_to_2(value: &mut Value) {
    let default_canvas = Canvas::default();
    let width = value
        .pointer("/canvas/width")
        .and_then(Value::as_u64)
        .unwrap_or(u64::from(default_canvas.width));
