fn frequency(slot: &str, value: f64) -> Result<(), String> {
    in_range(
        &format!("audio.eq.{slot}.frequency"),
        value,
        EQ_FREQUENCY_MIN,
        EQ_FREQUENCY_MAX,
    )
}

fn gain(slot: &str, value: f64) -> Result<(), String> {
    in_range(
        &format!("audio.eq.{slot}.gain_db"),
        value,
        -EQ_GAIN_MAX_DB,
