import json, re

root = "/Users/kevingalligan/devel/framejob/.claude/worktrees/help-docs/"
d = json.load(open(root + "build/Build/Products/Debug/Frame Job Debug.app/Contents/Resources/agent-catalog.json"))
tools = d if isinstance(d, list) else d.get("tools", d)
if isinstance(tools, dict):
    tools = list(tools.values())
T = {t["name"]: t for t in tools}
for p in ["tools-tracks-and-markers", "tools-set-audio", "tools-audio", "tools-clean-up"]:
    txt = open(root + f"docs/site/src/content/docs/mcp/{p}.mdx").read()
    secs = re.split(r"^## `([a-z_]+)`\s*$", txt, flags=re.M)
    for i in range(1, len(secs), 2):
        name, body = secs[i], secs[i + 1]
        body = body.split("\n## ")[0]
        rows = re.findall(r"^\| `([a-z_]+)` \| ([^|]+) \| (Yes|No) \|", body, flags=re.M)
        t = T.get(name)
        if not t:
            print("NO TOOL", name)
            continue
        props = t["inputSchema"]["properties"]
        req = set(t["inputSchema"].get("required", []))
        doc = {r[0] for r in rows}
        if doc != set(props):
            print("DIFF", p, name, "doc-only", doc - set(props), "cat-only", set(props) - doc)
        for a, ty, r in rows:
            if a in props:
                if (r == "Yes") != (a in req):
                    print("REQ", p, name, a, r, a in req)
                if a in ("project", "scope"):
                    continue
                pt = props[a].get("type")
                print(name, a, ty.strip(), pt, {k: v for k, v in props[a].items() if k in ("minimum", "maximum", "minItems", "enum")})

